package az.campuslink;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.annotation.PostConstruct;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import java.security.MessageDigest;
import java.security.SecureRandom;
import java.time.Instant;
import java.util.*;
import java.util.function.Function;

@RestController
@RequestMapping("/api/v1")
public class ApiController {
 private final JdbcTemplate db; private final ObjectMapper json; private final BCryptPasswordEncoder passwords=new BCryptPasswordEncoder(11);
 private final SecureRandom random=new SecureRandom();
 ApiController(JdbcTemplate db,ObjectMapper json){this.db=db;this.json=json;}
 @PostConstruct void seed(){if(count("courses")==0){for(String[] c:new String[][]{{"Java Backend with Spring Boot","Web Development"},{"Python for Data Analysis","AI & Data"},{"UI/UX Fundamentals","Design"},{"English Speaking Practice","Languages"}})db.update("INSERT INTO courses(title,category,provider) VALUES(?,?,?)",c[0],c[1],"CampusLink Demo");}if(count("partners")==0)db.update("INSERT INTO partners(name,type,location) VALUES(?,?,?)","CampusLink Demo Community","Organizations","Baku");}
 private int count(String t){return db.queryForObject("SELECT COUNT(*) FROM "+t,Integer.class);}
 private ApiException err(HttpStatus status,String message){return new ApiException(status,message);}
 private String s(Map<String,Object> b,String key,int limit){return Objects.toString(b.getOrDefault(key,""),"").trim().substring(0,Math.min(limit,Objects.toString(b.getOrDefault(key,""),"").trim().length()));}
 private long n(Object x){try{return Long.parseLong(String.valueOf(x));}catch(Exception e){return -1;}}
 private String digest(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 private String token(){byte[] bytes=new byte[32];random.nextBytes(bytes);return HexFormat.of().formatHex(bytes);}
 private long insert(String sql,Object...args){GeneratedKeyHolder keys=new GeneratedKeyHolder();db.update(c->{var p=c.prepareStatement(sql,new String[]{"id"});for(int i=0;i<args.length;i++)p.setObject(i+1,args[i]);return p;},keys);return Objects.requireNonNull(keys.getKey()).longValue();}
 private Map<String,Object> one(String sql,Object...args){List<Map<String,Object>> rows=db.queryForList(sql,args);return rows.isEmpty()?null:rows.get(0);}
 private List<Map<String,Object>> rows(String sql,Object...args){return db.queryForList(sql,args);}
 private Object decode(String value){try{return json.readValue(value,new TypeReference<List<String>>(){});}catch(Exception e){return List.of();}}
 private String encode(Object value){try{return json.writeValueAsString(value);}catch(Exception e){throw new IllegalStateException(e);}}
 private Map<String,Object> user(Map<String,Object> u){if(u==null)return null;Map<String,Object> r=new LinkedHashMap<>();r.put("id",u.get("id"));for(String k:List.of("full_name","email","university","major","bio","location","career_goal","language")){String out=switch(k){case "full_name"->"fullName";case "career_goal"->"careerGoal";default->k;};r.put(out,u.get(k));}r.put("skills",decode(Objects.toString(u.get("skills"),"[]")));return r;}
 private Map<String,Object> current(HttpServletRequest req){String header=Objects.toString(req.getHeader("Authorization"),"");if(!header.startsWith("Bearer "))throw err(HttpStatus.UNAUTHORIZED,"Please sign in");Map<String,Object> session=one("SELECT user_id FROM sessions WHERE token_hash=? AND expires_at>?",digest(header.substring(7)),System.currentTimeMillis());if(session==null)throw err(HttpStatus.UNAUTHORIZED,"Session expired. Sign in again");Map<String,Object> u=one("SELECT * FROM users WHERE id=?",session.get("user_id"));if(u==null)throw err(HttpStatus.UNAUTHORIZED,"User not found");return u;}
 private long uid(HttpServletRequest req){return n(current(req).get("id"));}
 private void notifyUser(long userId,String type,String title){db.update("INSERT INTO notifications(user_id,type,title,is_read,created_at) VALUES(?,?,?,FALSE,?)",userId,type,title,Instant.now().toString());}
 private Map<String,Object> loginResponse(Map<String,Object> u){String t=token();db.update("INSERT INTO sessions(token_hash,user_id,expires_at) VALUES(?,?,?)",digest(t),u.get("id"),System.currentTimeMillis()+7L*24*60*60*1000);return Map.of("token",t,"user",user(u));}
 @GetMapping("/health") public Object health(){return Map.of("status","ok","backend","spring-boot-java","storage","database");}
 @PostMapping("/auth/register") @Transactional public Object register(@RequestBody Map<String,Object> b){String name=s(b,"fullName",100),email=s(b,"email",255).toLowerCase(Locale.ROOT),password=Objects.toString(b.get("password"),"");if(name.isBlank()||!email.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$")||password.length()<8)throw err(HttpStatus.BAD_REQUEST,"Enter a name, valid email and password of at least 8 characters");if(one("SELECT id FROM users WHERE email=?",email)!=null)throw err(HttpStatus.CONFLICT,"Email already registered");long id=insert("INSERT INTO users(full_name,email,password_hash,skills) VALUES(?,?,?,?)",name,email,passwords.encode(password),"[]");return loginResponse(one("SELECT * FROM users WHERE id=?",id));}
 @PostMapping("/auth/login") public Object login(@RequestBody Map<String,Object> b){Map<String,Object> u=one("SELECT * FROM users WHERE email=?",s(b,"email",255).toLowerCase(Locale.ROOT));if(u==null||!passwords.matches(Objects.toString(b.get("password"),""),Objects.toString(u.get("password_hash"),"")))throw err(HttpStatus.UNAUTHORIZED,"Incorrect email or password");return loginResponse(u);}
 @PostMapping("/auth/logout") public Object logout(HttpServletRequest req){String h=Objects.toString(req.getHeader("Authorization"),"");if(h.startsWith("Bearer "))db.update("DELETE FROM sessions WHERE token_hash=?",digest(h.substring(7)));return Map.of("message","Logged out");}
 @GetMapping("/auth/me") public Object me(HttpServletRequest req){return user(current(req));}
 @GetMapping("/users") public Object users(HttpServletRequest req){current(req);return rows("SELECT * FROM users ORDER BY id DESC").stream().map(this::user).toList();}
 @PutMapping("/profile") public Object profile(HttpServletRequest req,@RequestBody Map<String,Object> b){long id=uid(req);for(String field:List.of("fullName","university","major","bio","location","careerGoal","language")){if(b.get(field) instanceof String){String column=switch(field){case "fullName"->"full_name";case "careerGoal"->"career_goal";default->field;};String val=s(b,field,field.equals("bio")?1000:200);if(field.equals("fullName")&&val.isBlank())continue;db.update("UPDATE users SET "+column+"=? WHERE id=?",val,id);}}if(b.get("skills") instanceof List<?> list)db.update("UPDATE users SET skills=? WHERE id=?",encode(list.stream().limit(30).map(String::valueOf).toList()),id);return user(one("SELECT * FROM users WHERE id=?",id));}
 @GetMapping("/courses") public Object courses(){return rows("SELECT id,title,category,provider FROM courses ORDER BY id");}
 @GetMapping("/partners") public Object partners(){return rows("SELECT id,name,type,location FROM partners ORDER BY id");}
 private Map<String,Object> team(Map<String,Object> t){Map<String,Object> r=new LinkedHashMap<>();r.put("id",t.get("id"));r.put("name",t.get("name"));r.put("description",t.get("description"));r.put("university",t.get("university"));r.put("category",t.get("category"));r.put("ownerId",t.get("owner_id"));r.put("memberIds",db.queryForList("SELECT user_id FROM team_members WHERE team_id=?",Long.class,t.get("id")));return r;}
 @GetMapping("/teams") public Object teams(){return rows("SELECT * FROM teams ORDER BY id DESC").stream().map(this::team).toList();}
 @PostMapping("/teams") @Transactional public Object createTeam(HttpServletRequest req,@RequestBody Map<String,Object> b){long u=uid(req);String name=s(b,"name",100);if(name.isBlank())throw err(HttpStatus.BAD_REQUEST,"Team name required");long id=insert("INSERT INTO teams(name,description,university,category,owner_id) VALUES(?,?,?,?,?)",name,s(b,"description",500),s(b,"university",200),s(b,"category",100),u);db.update("INSERT INTO team_members(team_id,user_id) VALUES(?,?)",id,u);return team(one("SELECT * FROM teams WHERE id=?",id));}
 @PostMapping("/teams/{id}/join") @Transactional public Object join(HttpServletRequest req,@PathVariable long id){long u=uid(req);Map<String,Object> t=one("SELECT * FROM teams WHERE id=?",id);if(t==null)throw err(HttpStatus.NOT_FOUND,"Team not found");if(one("SELECT user_id FROM team_members WHERE team_id=? AND user_id=?",id,u)==null){db.update("INSERT INTO team_members(team_id,user_id) VALUES(?,?)",id,u);long owner=n(t.get("owner_id"));if(owner>0&&owner!=u)notifyUser(owner,"TEAM",current(req).get("full_name")+" joined "+t.get("name"));}return team(t);}
 @GetMapping("/preferences") public Object preferences(HttpServletRequest req){Map<String,Object> p=one("SELECT data FROM preferences WHERE user_id=?",uid(req));if(p==null)return Map.of("saved",List.of(),"joined",List.of(),"exchanges",List.of());try{return json.readValue(String.valueOf(p.get("data")),Map.class);}catch(Exception e){return Map.of();}}
 @PutMapping("/preferences") public Object savePreferences(HttpServletRequest req,@RequestBody Map<String,Object> b){long id=uid(req);Map<String,Object> value=new HashMap<>();for(String k:List.of("saved","joined","exchanges"))if(b.get(k) instanceof List<?>)value.put(k,b.get(k));db.update("DELETE FROM preferences WHERE user_id=?",id);db.update("INSERT INTO preferences(user_id,data) VALUES(?,?)",id,encode(value));return value;}
 @PostMapping("/messages") public Object message(HttpServletRequest req,@RequestBody Map<String,Object> b){long from=uid(req),to=n(b.get("recipientId"));String content=s(b,"content",2000);if(from==to||content.isBlank()||one("SELECT id FROM users WHERE id=?",to)==null)throw err(HttpStatus.BAD_REQUEST,"Choose a recipient and a message");String now=Instant.now().toString();long id=insert("INSERT INTO messages(sender_id,recipient_id,content,created_at) VALUES(?,?,?,?)",from,to,content,now);notifyUser(to,"MESSAGE","New message from "+current(req).get("full_name"));return Map.of("id",id,"senderId",from,"recipientId",to,"content",content,"createdAt",now);}
 @GetMapping("/messages/{other}") public Object messages(HttpServletRequest req,@PathVariable long other){long me=uid(req);return rows("SELECT id,sender_id AS senderId,recipient_id AS recipientId,content,created_at AS createdAt FROM messages WHERE (sender_id=? AND recipient_id=?) OR (sender_id=? AND recipient_id=?) ORDER BY id",me,other,other,me);}
 private Map<String,Object> notification(Map<String,Object> n){return Map.of("id",n.get("id"),"userId",n.get("user_id"),"type",Objects.toString(n.get("type"),""),"title",Objects.toString(n.get("title"),""),"read",Boolean.TRUE.equals(n.get("is_read")),"createdAt",Objects.toString(n.get("created_at"),""));}
 @GetMapping("/notifications") public Object notifications(HttpServletRequest req){return rows("SELECT * FROM notifications WHERE user_id=? ORDER BY id DESC",uid(req)).stream().map(this::notification).toList();}
 @PatchMapping("/notifications/read-all") public Object readAll(HttpServletRequest req){db.update("UPDATE notifications SET is_read=TRUE WHERE user_id=?",uid(req));return Map.of("ok",true);}
 @PatchMapping("/notifications/{id}/read") public Object readOne(HttpServletRequest req,@PathVariable long id){long u=uid(req);if(db.update("UPDATE notifications SET is_read=TRUE WHERE id=? AND user_id=?",id,u)==0)throw err(HttpStatus.NOT_FOUND,"Notification not found");return notification(one("SELECT * FROM notifications WHERE id=?",id));}
 @PostMapping("/friends/requests") public Object friend(HttpServletRequest req,@RequestBody Map<String,Object> b){long from=uid(req),to=n(b.get("addresseeId"));if(from==to||one("SELECT id FROM users WHERE id=?",to)==null)throw err(HttpStatus.BAD_REQUEST,"Invalid friend");if(one("SELECT id FROM friendships WHERE (requester_id=? AND addressee_id=?) OR (requester_id=? AND addressee_id=?)",from,to,to,from)!=null)throw err(HttpStatus.CONFLICT,"Friend request already exists");long id=insert("INSERT INTO friendships(requester_id,addressee_id,status) VALUES(?,?,'PENDING')",from,to);notifyUser(to,"FRIEND",current(req).get("full_name")+" sent you a friend request");return Map.of("id",id,"requesterId",from,"addresseeId",to,"status","PENDING");}
 @GetMapping("/friends") public Object friends(HttpServletRequest req){long u=uid(req);return rows("SELECT id,requester_id AS requesterId,addressee_id AS addresseeId,status FROM friendships WHERE requester_id=? OR addressee_id=?",u,u);}
 @PostMapping("/friends/requests/{id}/accept") public Object accept(HttpServletRequest req,@PathVariable long id){long u=uid(req);Map<String,Object> f=one("SELECT * FROM friendships WHERE id=? AND addressee_id=?",id,u);if(f==null)throw err(HttpStatus.NOT_FOUND,"Friend request not found");db.update("UPDATE friendships SET status='ACCEPTED' WHERE id=?",id);notifyUser(n(f.get("requester_id")),"FRIEND",current(req).get("full_name")+" accepted your friend request");return Map.of("id",id,"requesterId",f.get("requester_id"),"addresseeId",u,"status","ACCEPTED");}
 @PostMapping("/enrollments") public Object enroll(HttpServletRequest req,@RequestBody Map<String,Object> b){long u=uid(req),c=n(b.get("courseId"));if(one("SELECT id FROM courses WHERE id=?",c)==null)throw err(HttpStatus.NOT_FOUND,"Course not found");Map<String,Object> e=one("SELECT * FROM enrollments WHERE user_id=? AND course_id=?",u,c);if(e==null){long id=insert("INSERT INTO enrollments(user_id,course_id,progress) VALUES(?,?,0)",u,c);return Map.of("id",id,"userId",u,"courseId",c,"progress",0);}return Map.of("id",e.get("id"),"userId",u,"courseId",c,"progress",e.get("progress"));}
 @GetMapping("/enrollments") public Object enrollments(HttpServletRequest req){return rows("SELECT id,user_id AS userId,course_id AS courseId,progress FROM enrollments WHERE user_id=?",uid(req));}
 @PostMapping("/exchanges") public Object exchange(HttpServletRequest req,@RequestBody Map<String,Object> b){long from=uid(req),to=n(b.get("targetId"));if(from==to||one("SELECT id FROM users WHERE id=?",to)==null)throw err(HttpStatus.BAD_REQUEST,"Select a student");Map<String,Object> e=one("SELECT id FROM exchanges WHERE user_id=? AND target_id=?",from,to);long id=e==null?insert("INSERT INTO exchanges(user_id,target_id,status) VALUES(?,?,'PENDING')",from,to):n(e.get("id"));if(e==null)notifyUser(to,"EXCHANGE",current(req).get("full_name")+" requested a skill exchange");return Map.of("id",id,"userId",from,"targetId",to,"status","PENDING");}
 @PostMapping("/inquiries") public Object inquiry(HttpServletRequest req,@RequestBody Map<String,Object> b){long u=uid(req);String msg=s(b,"message",1000);if(msg.isBlank())throw err(HttpStatus.BAD_REQUEST,"Inquiry required");long id=insert("INSERT INTO inquiries(user_id,message) VALUES(?,?)",u,msg);return Map.of("id",id,"userId",u,"message",msg);}
}
